<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
Auth::requireAuthenticated();
if (Auth::isAdmin()) { header('Location: /index.php'); exit; }
Auth::ensureUserSchema();
$pdo=Database::connection();ensure_member_soft_delete_schema($pdo);ensure_member_type_schema($pdo);
$memberId=Auth::memberId();
if($memberId<=0){http_response_code(403);exit('Dit gebruikersaccount is niet aan een ledenfiche gekoppeld.');}
$year=(int)date('Y');$message='';$error='';
function load_own_member(PDO $pdo,int $id,int $year):array{
 $s=$pdo->prepare('SELECT m.*,ms.payment_status,ms.paid_at,ms.free_flight_entitled,ms.free_flight_date FROM members m LEFT JOIN memberships ms ON ms.member_id=m.id AND ms.membership_year=:y WHERE m.id=:id AND m.deleted_at IS NULL');$s->execute(['id'=>$id,'y'=>$year]);$m=$s->fetch();if(!$m){http_response_code(404);exit('Ledenfiche niet gevonden.');}return $m;
}
$member=load_own_member($pdo,$memberId,$year);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'profile');
 try{
  if($action==='profile'){
   $first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));
   if($first===''||$last==='')throw new RuntimeException('Voornaam en familienaam zijn verplicht.');
   if($email===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Vul een geldig e-mailadres in.');
   $pdo->beginTransaction();
   $u=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=:email AND id<>:id LIMIT 1');$u->execute(['email'=>$email,'id'=>(int)$_SESSION['user_id']]);if($u->fetchColumn())throw new RuntimeException('Dit e-mailadres is al aan een ander account gekoppeld.');
   $pdo->prepare('UPDATE members SET first_name=:f,last_name=:l,address=:a,postal_code=:p,city=:c,birth_date=:b,mobile=:m,email=:e,weight_kg=:w WHERE id=:id')->execute(['f'=>$first,'l'=>$last,'a'=>trim((string)($_POST['address']??''))?:null,'p'=>trim((string)($_POST['postal_code']??''))?:null,'c'=>trim((string)($_POST['city']??''))?:null,'b'=>($_POST['birth_date']??'')?:null,'m'=>trim((string)($_POST['mobile']??''))?:null,'e'=>$email,'w'=>($_POST['weight_kg']??'')!==''?(float)str_replace(',','.',(string)$_POST['weight_kg']):null,'id'=>$memberId]);
   $name=trim($first.' '.$last);$pdo->prepare('UPDATE users SET name=:n,email=:e WHERE id=:id')->execute(['n'=>$name,'e'=>$email,'id'=>(int)$_SESSION['user_id']]);
   $_SESSION['user_name']=$name;$_SESSION['user_email']=$email;$pdo->commit();$message='Je gegevens zijn opgeslagen.';
  }elseif($action==='password'){
   $current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
   $s=$pdo->prepare('SELECT password_hash FROM users WHERE id=:id');$s->execute(['id'=>(int)$_SESSION['user_id']]);$hash=(string)$s->fetchColumn();
   if(!password_verify($current,$hash))throw new RuntimeException('Je huidige wachtwoord is niet correct.');
   if(strlen($new)<10)throw new RuntimeException('Het nieuwe wachtwoord moet minstens 10 tekens bevatten.');
   if($new!==$confirm)throw new RuntimeException('De nieuwe wachtwoorden zijn niet gelijk.');
   $pdo->prepare('UPDATE users SET password_hash=:h WHERE id=:id')->execute(['h'=>password_hash($new,PASSWORD_DEFAULT),'id'=>(int)$_SESSION['user_id']]);$message='Je wachtwoord is gewijzigd.';
  }elseif($action==='photo_delete'){
   if(!empty($member['photo_path'])){$old=basename((string)$member['photo_path']);$path=__DIR__.'/uploads/members/'.$old;if(is_file($path))@unlink($path);}
   $pdo->prepare('UPDATE members SET photo_path=NULL WHERE id=:id')->execute(['id'=>$memberId]);$message='Je foto is verwijderd.';
  }elseif($action==='photo_upload'){
   if(!isset($_FILES['photo'])||($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Selecteer een foto.');
   if((int)$_FILES['photo']['size']>5*1024*1024)throw new RuntimeException('De foto mag maximaal 5 MB groot zijn.');
   $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($_FILES['photo']['tmp_name']);$exts=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($exts[$mime]))throw new RuntimeException('Gebruik JPG, PNG of WEBP.');
   $dir=__DIR__.'/uploads/members';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Uploadmap kon niet worden aangemaakt.');
   $filename='member-'.$memberId.'-'.bin2hex(random_bytes(8)).'.'.$exts[$mime];if(!move_uploaded_file($_FILES['photo']['tmp_name'],$dir.'/'.$filename))throw new RuntimeException('Foto kon niet worden opgeslagen.');
   if(!empty($member['photo_path'])){$old=__DIR__.'/uploads/members/'.basename((string)$member['photo_path']);if(is_file($old))@unlink($old);}
   $pdo->prepare('UPDATE members SET photo_path=:p WHERE id=:id')->execute(['p'=>'/uploads/members/'.$filename,'id'=>$memberId]);$message='Je foto is aangepast.';
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
 $member=load_own_member($pdo,$memberId,$year);
}
$typeLabel=['viewer'=>'VIEWER','flyer'=>'FLYER','pilot'=>'PILOT'][$member['member_type']]??strtoupper((string)$member['member_type']);
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mijn profiel | Heli One</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0;color:#171717}.member-header{background:#111;color:#fff;padding:15px 28px;display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{display:flex;align-items:center;gap:20px}.brand img{width:190px;height:auto}.member-header a{color:#fff}main{max-width:1050px;margin:32px auto;padding:0 22px}.hero,.card{background:#fff;border-radius:14px;padding:24px;box-shadow:0 4px 18px #0000000d;margin:18px 0}.hero{display:flex;gap:22px;align-items:center}.photo{width:130px;height:170px;object-fit:cover;border-radius:10px;background:#e7eaee}.muted{color:#68707a}.pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#eef1f4;font-weight:700;font-size:13px;margin-right:6px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}label{display:block;font-weight:700;font-size:14px;margin-bottom:6px}input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #d4d9df;border-radius:8px;font:inherit}.btn{display:inline-block;padding:11px 16px;border:0;border-radius:9px;background:#111;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.secondary{background:#e7eaee;color:#111}.danger{background:#981b1b}.actions{display:flex;gap:9px;flex-wrap:wrap}.ok,.err{padding:12px 14px;border-radius:9px}.ok{background:#e9f8ee}.err{background:#feecec}.readonly{background:#f7f8fa;padding:12px;border-radius:9px}.photoforms{display:flex;gap:10px;flex-wrap:wrap;align-items:end}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{align-items:flex-start;flex-direction:column}.member-header{padding:13px 16px;flex-direction:column;align-items:flex-start}.brand img{width:145px}}</style></head><body><header class="member-header"><div class="brand"><img src="/assets/HeliOne%20-%20Logo%20Wit.png" alt="Heli One"><strong>Mijn Heli One</strong></div><div><?=e((string)$_SESSION['user_name'])?> · <a href="/logout.php">Afmelden</a></div></header><main><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif;?><?php if($error):?><p class="err"><?=e($error)?></p><?php endif;?><section class="hero"><?php if(!empty($member['photo_path'])):?><img class="photo" src="<?=e($member['photo_path'])?>" alt="Pasfoto"><?php else:?><div class="photo"></div><?php endif;?><div><h1><?=e($member['first_name'].' '.$member['last_name'])?></h1><p class="muted">Lidnummer <strong><?=e($member['member_number']??'')?></strong></p><span class="pill"><?=$typeLabel?></span><span class="pill"><?=($member['status']??'active')==='active'?'Actief':'Inactief'?></span><p>Betaling <?=$year?>: <strong><?=($member['payment_status']??'unpaid')==='paid'?'Betaald':'Niet betaald'?></strong><?php if($member['member_type']==='flyer'):?> · Gratis vlucht: <strong><?=!empty($member['free_flight_date'])?'Uitgevoerd op '.e($member['free_flight_date']):'Recht aanwezig'?></strong><?php endif;?></p><div class="actions"><a class="btn" href="/badge.php?id=<?=$memberId?>">Mijn badge bekijken</a><a class="btn secondary" target="_blank" href="/badge.php?id=<?=$memberId?>&mode=print">Badge afdrukken</a></div></div></section><section class="card"><h2>Mijn gegevens</h2><p class="muted">Lidtype, betaalstatus, lidnummer en vluchttoekenning worden door Heli One beheerd.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="grid"><div><label>Voornaam</label><input name="first_name" required value="<?=e($member['first_name'])?>"></div><div><label>Familienaam</label><input name="last_name" required value="<?=e($member['last_name'])?>"></div><div class="full"><label>Straat + nr</label><input name="address" value="<?=e($member['address'])?>"></div><div><label>Postcode</label><input name="postal_code" value="<?=e($member['postal_code'])?>"></div><div><label>Stad</label><input name="city" value="<?=e($member['city'])?>"></div><div><label>Geboortedatum</label><input type="date" name="birth_date" value="<?=e($member['birth_date'])?>"></div><div><label>GSM</label><input name="mobile" value="<?=e($member['mobile'])?>"></div><div><label>E-mail</label><input type="email" name="email" required value="<?=e($member['email']?:($_SESSION['user_email']??''))?>"></div><div><label>Gewicht (kg)</label><input type="number" min="0" max="999" step="0.1" name="weight_kg" value="<?=e((string)$member['weight_kg'])?>"></div><div><label>Lid sinds</label><div class="readonly"><?=e($member['member_since']??'')?></div></div></div><p><button class="btn" type="submit">Gegevens opslaan</button></p></form></section><section class="card"><h2>Mijn foto</h2><div class="photoforms"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="photo_upload"><label>Nieuwe pasfoto</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><p><button class="btn" type="submit">Foto uploaden</button></p></form><?php if(!empty($member['photo_path'])):?><form method="post" onsubmit="return confirm('Je huidige foto verwijderen?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="photo_delete"><button class="btn danger" type="submit">Foto verwijderen</button></form><?php endif;?></div></section><section class="card"><h2>Wachtwoord wijzigen</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><div class="grid"><div class="full"><label>Huidig wachtwoord</label><input type="password" name="current_password" autocomplete="current-password" required></div><div><label>Nieuw wachtwoord</label><input type="password" name="new_password" minlength="10" autocomplete="new-password" required></div><div><label>Herhaal nieuw wachtwoord</label><input type="password" name="confirm_password" minlength="10" autocomplete="new-password" required></div></div><p><button class="btn" type="submit">Wachtwoord wijzigen</button></p></form></section></main><script src="/assets/member-photo-cropper.js?v=2"></script></body></html>